import math
    import random
    import time

    LANGUAGE_WRAPPER = 'The Bank of Pittsburgh issues coins that have a heads side and a tails side. Vera has a row of {n} such coins alternately tails-up and heads-up, with the leftmost coin tails-up. On a move, Vera may flip over one coin, subject to the rules: (i) on the first move, Vera may flip any of the {n} coins; (ii) on all subsequent moves, Vera may only flip over a coin adjacent to the coin she flipped on the previous move. Additionally, flipping the i-th coin incurs a cost c_i, and the costs are given in order from left to right as: [costs_str]. Determine the smallest possible total cost Vera can incur to reach a state in which every coin is heads-up.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose n moderately large to avoid trivial cases but keep the verifier simple
n = rng.randint(5, 60)  # ensure at least one interior coin
# Generate diverse positive integer costs
costs = [rng.randint(1, 50) for _ in range(n)]
# Ensure not all costs are equal (to avoid trivial uniform-cost instances)
if len(set(costs)) == 1:
    # retry once; if still uniform, tweak one entry
    costs = [rng.randint(1, 50) for _ in range(n)]
    if len(set(costs)) == 1:
        idx = rng.randint(0, n-1)
        costs[idx] = costs[idx] + 1
costs_str = " ".join(str(x) for x in costs)
return {'n': n, 'costs_str': costs_str, 'costs': costs}

    def verifier(assign):
# Validate the assignment and compute the minimal total cost.
# The initial arrangement is alternating tails/head, starting with tails at the leftmost coin.
# Costs are given; on each move Vera flips exactly one coin, with adjacency constraint (path walk).
# Claim (to compute answer):
# Let c_i be costs. Then minimal total cost equals:
#  - For odd n: c_1 + 2*sum_{i=2}^{n-1} c_i + c_n
#  - For even n: c_1 + 2*sum_{i=2}^{n-1} c_i
# This corresponds to flipping each interior coin exactly twice, the left endpoint once,
# and the right endpoint once iff it is initially tails (i.e., when n is odd).
try:
    n = int(assign.get('n'))
    costs_str = assign.get('costs_str')
    costs = assign.get('costs')
except Exception:
    # malformed
    return (False, None)
# Basic validation
if not isinstance(n, int) or n < 1:
    # invalid n
    return (False, None)
if not isinstance(costs_str, str):
    return (False, None)
# Parse costs_str and ensure consistency
try:
    parsed = [int(x) for x in costs_str.strip().split()] if costs_str.strip() else []
except Exception:
    return (False, None)
if len(parsed) != n:
    # mismatch in provided costs length versus n
    return (False, None)
if any(x <= 0 for x in parsed):
    # costs must be positive
    return (False, None)
# If the generator provided a 'costs' list, cross-check
if costs is not None:
    if not isinstance(costs, list) or len(costs) != n:
        return (False, None)
    try:
        costs_ok = all(isinstance(x, int) for x in costs)
    except Exception:
        return (False, None)
    if not costs_ok:
        return (False, None)
    if costs != parsed:
        # ensure wrapper and internal agree
        return (False, None)
c = parsed
# Difficulty guard: ensure non-trivial variety in costs and presence of interior coins
if n < 5:
    return (False, None)
# compute minimal total cost
interior_sum = sum(c[1:n-1]) if n >= 3 else 0
if n % 2 == 1:
    answer = c[0] + 2 * interior_sum + c[-1]
else:
    answer = c[0] + 2 * interior_sum
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

